UPDATE "Item" SET "context" = 'A noun names a person, place, thing, or idea. ''Dog'' names an animal. ''Happy'' describes the dog, ''barked'' is what it did, and ''loudly'' tells how.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'pos-g3-001';
UPDATE "Item" SET "context" = 'A verb is an action word. ''Barked'' is what the dog did. ''Dog'' is a noun, ''happy'' describes it, and ''loudly'' tells how it barked.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'pos-g3-002';
UPDATE "Item" SET "context" = 'An adjective describes a noun. ''Happy'' tells what kind of dog it is. ''Dog'' is a noun, ''barked'' is a verb, and ''loudly'' tells how (an adverb).', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'pos-g3-003';
UPDATE "Item" SET "choices" = '["bright", "ran", "school", "quickly"]', "context" = 'A noun names a person, place, or thing. ''School'' is a place. ''Ran'' is an action (verb), ''quickly'' tells how (adverb), and ''bright'' describes (adjective).', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'pos-g3-004';
UPDATE "Item" SET "context" = '''Quickly'' tells how she ran, so it''s an adverb. Many adverbs end in -ly. ''She'' is a pronoun, ''ran'' is a verb, and ''field'' is a noun.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'pos-g4-001';
UPDATE "Item" SET "context" = '''On'' shows where the book is compared to the table, so it''s a preposition. ''Book'' and ''table'' are nouns, and ''is'' is a verb.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'pos-g5-001';
UPDATE "Item" SET "context" = '''And'' joins ''apples'' and ''oranges,'' so it''s a conjunction. Other conjunctions: but, or, so, because.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'pos-g5-003';
UPDATE "Item" SET "prompt" = 'In ''The girl who won the race is my sister,'' what part of speech is WHO?', "context" = 'WHO stands in for ''the girl'' and starts the part that tells which girl (who won the race). A word that does that is a relative pronoun. Who, whom, whose, and which work this way too.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'pos-g6-002';
