UPDATE "Item" SET "context" = 'Shout and yell both mean to call out loudly. Whisper and mumble are quiet ways to talk.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'saah-syn-g3-002';
