UPDATE "Item" SET "context" = 'Ancient means very, very old, like the pyramids. Modern means new, from today. Old and historic are close to ancient, not opposite.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'saah-ant-g4-001';
