UPDATE "Item" SET "choices" = '["whether", "wetter", "weaker", "feather"]', "context" = 'Weather is what it''s like outside: sunny, rainy, or windy. Whether means ''if'' (I don''t know whether to go). They sound the same but are spelled differently.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'saah-hom-g4-002';
UPDATE "Item" SET "context" = 'Courageous means full of courage, which is the same as brave. Scared is the opposite.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'saah-syn-g4-001';
