UPDATE "Item" SET "context" = 'Abundant means there''s plenty of something. Scarce means there''s very little. Plentiful means the same as abundant.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'saah-ant-g5-001';
UPDATE "Item" SET "context" = 'To expand is to get bigger, like a balloon filling with air. To shrink is to get smaller. Grow and stretch are close to expand.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'saah-ant-g5-002';
UPDATE "Item" SET "choices" = '["prince", "practical", "print", "principle"]', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'saah-hom-g5-001';
