UPDATE "Item" SET "context" = 'A diligent person works hard and keeps at it. Lazy is the opposite.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'saah-syn-g5-001';
UPDATE "Item" SET "context" = 'Benevolent means kind and wanting to help others. ''Bene'' means good, like in ''benefit.'' Cruel is the opposite.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'saah-syn-g5-002';
UPDATE "Item" SET "context" = 'Reluctant means you don''t really want to do something. Eager is the opposite: really wanting to.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'saah-syn-g5-003';
UPDATE "Item" SET "choices" = '["clear", "shiny", "visible", "opaque"]', "context" = 'Transparent means you can see through it, like a clean window. Opaque means you can''t see through it at all, like a wooden door. Clear means the same as transparent.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'saah-ant-g6-001';
UPDATE "Item" SET "context" = 'Frugal means careful not to waste money or things. Wasteful is the opposite. Thrifty means the same as frugal.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'saah-ant-g6-002';
UPDATE "Item" SET "choices" = '["effort", "infect", "affront", "effect"]', "context" = 'In everyday speech affect and effect usually sound the same. Affect is usually a verb meaning to change something (The rain affected the game). Effect is usually a noun meaning the result (The effect was huge).', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'saah-hom-g6-001';
UPDATE "Item" SET "context" = 'Meticulous means very careful about every small detail. Careless is the opposite.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'saah-syn-g6-001';
UPDATE "Item" SET "context" = 'Obsolete means no longer used because something newer replaced it, like a VCR. Outdated means the same. Modern is the opposite.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'saah-syn-g6-002';
