UPDATE "Item" SET "context" = 'The Sun is a star, the closest one to Earth. The Moon goes around Earth, and Mars and Earth are planets that go around the Sun.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'sci-g2-001';
UPDATE "Item" SET "context" = 'Most things around you are a solid (like a rock), a liquid (like milk), or a gas (like the air you breathe).', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'sci-g2-003';
UPDATE "Item" SET "context" = 'Water is a liquid: it flows and takes the shape of its cup. Ice is water frozen into a solid, and steam is water turned into a gas.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'sci-g2-004';
UPDATE "Item" SET "choices" = '["Sunlight, water, and air", "Moonlight, sand, and rocks", "Darkness, water, and sugar", "Snow, soil, and moonlight"]', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'sci-g2-005';
UPDATE "Item" SET "context" = 'Chickens are birds, and all birds lay eggs. Dogs, cats, and cows are mammals, and their babies are born alive.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'sci-g2-006';
UPDATE "Item" SET "context" = 'Mercury is the closest planet to the Sun. Order from the Sun: Mercury, Venus, Earth, Mars.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'sci-g3-002';
