UPDATE "Item" SET "context" = 'Your heart is a muscle about the size of your fist. It squeezes to push blood all around your body.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'sci-g3-004';
UPDATE "Item" SET "context" = 'Your lungs fill with air when you breathe in. They pass oxygen into your blood.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'sci-g3-005';
UPDATE "Item" SET "context" = 'Evaporation is when liquid water turns into a gas called water vapor, like a puddle drying up in the sun. Condensation is the opposite: vapor turning back into drops.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'sci-g3-006';
UPDATE "Item" SET "context" = 'Mercury is closest to the Sun and Neptune is farthest. Use the memory sentence: each word starts with a planet''s first letter.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'sci-g4-001';
UPDATE "Item" SET "context" = 'Your skin covers your whole body, which makes it the largest organ. The liver is the largest organ inside your body.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'sci-g4-004';
UPDATE "Item" SET "context" = 'Gravity is the pull that makes a dropped ball fall to the ground. It also keeps the Moon going around Earth.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'sci-g4-005';
UPDATE "Item" SET "answer" = 'Water rising into clouds and falling back as rain, over and over', "choices" = '["Water rising into clouds and falling back as rain, over and over", "The Moon pulling ocean water into high and low tides each day", "Water being cleaned at a plant and piped into our homes", "Waves crashing on the beach and rolling back out to sea"]', "context" = 'The sun warms water so it evaporates into the air. The vapor cools into clouds (condensation), then falls as rain or snow (precipitation). Then it all starts again.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'sci-g4-006';
UPDATE "Item" SET "context" = 'Igneous rock forms when melted rock cools. Sedimentary rock forms from layers of sand and mud pressed together. Metamorphic rock is changed by heat and squeezing. (Granite, limestone, and marble are one of each.)', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'sci-g5-001';
UPDATE "Item" SET "choices" = '["Cell wall and chloroplasts", "Nucleus and cytoplasm", "Cell membrane and nucleus", "Cytoplasm and cell membrane"]', "prompt" = 'What do plant cells have that animal cells do NOT?', "context" = 'Plant cells have a stiff cell wall for support and chloroplasts that use sunlight to make food. Plant and animal cells both have a nucleus, cytoplasm, and a cell membrane.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'sci-g5-002';
UPDATE "Item" SET "prompt" = 'What is the smallest living unit that all living things are made of?', "context" = 'Cells are the smallest living units: every plant, animal, and person is built from them. Atoms are much smaller, but an atom on its own isn''t alive.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'sci-g5-003';
UPDATE "Item" SET "context" = 'Herbivores eat only plants, like cows and rabbits. ''Herbi'' comes from an old word for plants, like herbs. Carnivores eat meat.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'sci-g5-004';
UPDATE "Item" SET "prompt" = 'When you breathe in, which gas from the air does your body use?', "context" = 'Your body uses oxygen to get energy from food. Air is mostly nitrogen, but you breathe it right back out without using it.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'sci-g5-006';
UPDATE "Item" SET "prompt" = 'Which waste gas does your body make and then breathe out?', "context" = 'When your body uses oxygen, it makes carbon dioxide as waste, and you breathe it out. Plants take in that carbon dioxide to make their food.', "updatedAt" = (CAST(strftime('%s','now') AS INTEGER) * 1000) WHERE "id" = 'sci-g5-007';
